151	/// Keeps track of where a paginated listing left off. As the file scan goes newest -> oldest,
152	/// it ignores everything until it passes the last seen timestamp from the previous page, then
153	/// starts returning results after that. This makes paging stable even if new files show up during
154	/// pagination.
155	struct AnchorState {
156	    ts: OffsetDateTime,
157	    passed: bool,
158	}
159	
160	impl AnchorState {
161	    fn new(anchor: Option<Cursor>) -> Self {
162	        match anchor {
163	            Some(cursor) => Self {
164	                ts: cursor.ts,
165	                passed: false,
166	            },
167	            None => Self {
168	                ts: OffsetDateTime::UNIX_EPOCH,
169	                passed: true,
170	            },
171	        }
172	    }
173	
174	    fn should_skip(&mut self, ts: OffsetDateTime, _id: Uuid) -> bool {
175	        if self.passed {
176	            return false;
177	        }
178	        if ts < self.ts {
179	            self.passed = true;
180	            false
181	        } else {
182	            true
183	        }
184	    }
185	}
